import { assertEquals } from 'jsr:@std/assert'
import { afterEach, beforeEach, describe, it } from 'jsr:@std/testing/bdd'
import { assertSpyCalls, spy } from 'jsr:@std/testing/mock'
import EdgeFunction from '../../process-ticket/index.ts'

const env = { url: 'http://mocksupabase', publishableKeys: { default: 'sb_publishable_xy' }, secretKeys: { default: 'sb_secret_xy' } }

describe('fn', () => {
  const originalFetch = globalThis.fetch
  beforeEach(() => {
    Deno.env.set('SUPABASE_URL', env.url)
    Deno.env.set('SUPABASE_PUBLISHABLE_KEYS', JSON.stringify(env.publishableKeys))
    Deno.env.set('SUPABASE_SECRET_KEYS', JSON.stringify(env.secretKeys))
    // for auth:'user' also set SUPABASE_JWKS and sign an RS256 JWT with jsr:@panva/jose@6
  })
  afterEach(() => { globalThis.fetch = originalFetch })

  it('calls PostgREST', async () => {
    const mock = spy(async (input: RequestInfo | URL): Promise<Response> =>
      input.toString() === `${env.url}/rest/v1/profiles?select=age&limit=1`
        ? Response.json({ age: 8 })
        : new Response(null, { status: 404 }))
    globalThis.fetch = mock
    const res = await EdgeFunction.fetch(new Request(`${env.url}/functions/v1/process-ticket`, {
      method: 'POST', headers: { apikey: env.publishableKeys.default, Authorization: `Bearer <jwt>` },
      body: JSON.stringify({ price: 10 }) }))
    assertEquals(res.status, 200)
    assertSpyCalls(mock, 1)
  })
})
